#!/bin/bash
# Uninstall script for Zed Attack Proxy
# Generated by IntuneBrew

# Exit on error
set -e

echo "Uninstalling Zed Attack Proxy..."

# Check if running as root
if [ "$EUID" -ne 0 ]; then
  echo "Please run as root"
  exit 1
fi

# Kill application process if running
echo "Stopping Zed Attack Proxy if running..."
pkill -f "Zed Attack Proxy" 2>/dev/null || true

# Remove /Applications/ZAP.app
echo "Removing /Applications/ZAP.app..."
if [ -d "/Applications/ZAP.app" ]; then
    rm -rf "/Applications/ZAP.app" 2>/dev/null || true
elif [ -f "/Applications/ZAP.app" ]; then
    rm -f "/Applications/ZAP.app" 2>/dev/null || true
fi

# Remove $HOME/Library/Application Support/ZAP
echo "Removing $HOME/Library/Application Support/ZAP..."
if [ -d "$HOME/Library/Application Support/ZAP" ]; then
    rm -rf "$HOME/Library/Application Support/ZAP" 2>/dev/null || true
elif [ -f "$HOME/Library/Application Support/ZAP" ]; then
    rm -f "$HOME/Library/Application Support/ZAP" 2>/dev/null || true
fi

# Remove $HOME/Library/Preferences/org.zaproxy.zap.plist
echo "Removing $HOME/Library/Preferences/org.zaproxy.zap.plist..."
if [ -d "$HOME/Library/Preferences/org.zaproxy.zap.plist" ]; then
    rm -rf "$HOME/Library/Preferences/org.zaproxy.zap.plist" 2>/dev/null || true
elif [ -f "$HOME/Library/Preferences/org.zaproxy.zap.plist" ]; then
    rm -f "$HOME/Library/Preferences/org.zaproxy.zap.plist" 2>/dev/null || true
fi

echo "Uninstallation complete!"
exit 0
